using LinearAlgebra;
using LinearAlgebra.Sparse;
using NUnit.Framework;
using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;

// Block (multi-RHS) CG: Krylov.bcg(in A, in B, ref X) where B/X are s ROWS x n COLS (row = RHS). A true
// block method (one shared subspace, s x s coefficients, ApplyBlock per iteration), NOT s scalar solves.
// Every test runs inside a [BurstCompile] IJob (by-value struct copy), so the job-safety criterion --
// the caller sees the final X written through the ref doubleMxN -- is exercised by construction.
public class doubleBlockCGTests
{
    [BurstCompile(CompileSynchronously = true)]
    public struct BlockCGTestJob : IJob
    {
        public enum TestType
        {
            MatchesScalarCgPerColumn,
            BlockAdvantageIterations,
            RankDeficientBlockDeflates,
            PreconditionedMatchesScalar,
            KnownSolutionRecovered,
        }

        public TestType Type;

        public void Execute()
        {
            switch (Type)
            {
                case TestType.MatchesScalarCgPerColumn:   MatchesScalarCgPerColumn();   break;
                case TestType.BlockAdvantageIterations:   BlockAdvantageIterations();   break;
                case TestType.RankDeficientBlockDeflates: RankDeficientBlockDeflates(); break;
                case TestType.PreconditionedMatchesScalar: PreconditionedMatchesScalar(); break;
                case TestType.KnownSolutionRecovered:      KnownSolutionRecovered();      break;
            }
        }

        static double Tol() => 1e-5;

        static doubleMxN BuildDenseSPD(ref Arena arena, int dim, uint seed)
        {
            var M = arena.doubleRandomMat(dim, dim, (double)(-1f), (double)1f, seed);
            var A = Blas.dot(M, M, true);                       // M^T M
            for (int d = 0; d < dim; d++) A[d, d] += dim;       // diagonally boost -> SPD, well-conditioned
            return A;
        }

        static doubleN Row(ref Arena arena, in doubleMxN B, int j, int n)
        {
            var v = arena.doubleVec(n);
            for (int c = 0; c < n; c++) v[c] = B[j, c];
            return v;
        }

        // Each column of the block solution matches an independent scalar cg solve of that column, and
        // every column reached tolerance.
        void MatchesScalarCgPerColumn()
        {
            var arena = new Arena(Allocator.Persistent);

            int n = 20, s = 4;
            var A = BuildDenseSPD(ref arena, n, 71001u);
            var B = arena.doubleRandomMat(s, n, (double)(-1f), (double)1f, 71002u);

            var X = arena.doubleMat(s, n);                      // zero initial guess
            var info = Krylov.bcg(in A, in B, ref X, 8 * n, Consts.doubleSqrtEps);

            Assert.IsTrue(info.Solved);
            Assert.AreEqual(s, info.converged);
            Assert.AreEqual(s, info.rhs);

            for (int j = 0; j < s; j++)
            {
                var bj = Row(ref arena, in B, j, n);
                var xj = arena.doubleVec(n);
                Assert.IsTrue(Krylov.cg(in A, in bj, ref xj, 8 * n, Consts.doubleSqrtEps));

                // Block column j matches the scalar solve (both converged to the same unique solution).
                for (int c = 0; c < n; c++)
                    Assert.IsTrue(math.abs((double)X[j, c] - (double)xj[c]) <= Tol() * (1.0 + math.abs((double)xj[c])));
            }

            arena.Dispose();
        }

        // The block solve converges in <= the worst single-column scalar iteration count (the block
        // advantage: all RHS share the richer block Krylov subspace).
        void BlockAdvantageIterations()
        {
            var arena = new Arena(Allocator.Persistent);

            int n = 24, s = 5;
            var A = BuildDenseSPD(ref arena, n, 72001u);
            var B = arena.doubleRandomMat(s, n, (double)(-1f), (double)1f, 72002u);
            double tol = Consts.doubleSqrtEps;
            int budget = 8 * n;

            var X = arena.doubleMat(s, n);
            var blockInfo = Krylov.bcg(in A, in B, ref X, budget, tol);
            Assert.IsTrue(blockInfo.Solved);

            int worstScalar = 0;
            for (int j = 0; j < s; j++)
            {
                var bj = Row(ref arena, in B, j, n);
                var xj = arena.doubleVec(n);
                var si = Krylov.cg(in A, in bj, ref xj, budget, tol);
                Assert.IsTrue(si.Solved);
                if (si.iterations > worstScalar) worstScalar = si.iterations;
            }

            // block iters must be <= the worst single-column scalar iters (the block advantage)
            Assert.IsTrue(blockInfo.iterations <= worstScalar);

            arena.Dispose();
        }

        // A rank-deficient RHS block (two identical columns) must NOT NaN or throw -- the ridge-
        // regularized s x s solve deflates the dependent direction and still solves every column.
        void RankDeficientBlockDeflates()
        {
            var arena = new Arena(Allocator.Persistent);

            int n = 16, s = 4;
            var A = BuildDenseSPD(ref arena, n, 73001u);
            var B = arena.doubleRandomMat(s, n, (double)(-1f), (double)1f, 73002u);
            // Force columns 1 and 3 identical -> block rank <= 3.
            for (int c = 0; c < n; c++) B[3, c] = B[1, c];

            var X = arena.doubleMat(s, n);
            var info = Krylov.bcg(in A, in B, ref X, 8 * n, Consts.doubleSqrtEps);

            // Finite, no NaN, and every column solved (system is consistent for each column).
            for (int j = 0; j < s; j++)
                for (int c = 0; c < n; c++)
                    Assert.IsFalse(double.IsNaN((double)X[j, c]) || double.IsInfinity((double)X[j, c]));

            Assert.IsTrue(info.Solved);
            // The two identical RHS get the same solution.
            for (int c = 0; c < n; c++)
                Assert.IsTrue(math.abs((double)X[1, c] - (double)X[3, c]) <= Tol() * (1.0 + math.abs((double)X[1, c])));

            arena.Dispose();
        }

        // Block-Jacobi-preconditioned block-CG over a BSR SPD system matches per-column scalar pcg.
        void PreconditionedMatchesScalar()
        {
            var arena = new Arena(Allocator.Persistent);

            int n = 18, s = 3;
            var Adense = BuildDenseSPD(ref arena, n, 74001u);
            var A = DenseToBSR1x1(ref arena, in Adense, n * n);
            var M = arena.doubleBlockJacobi(in A);
            var B = arena.doubleRandomMat(s, n, (double)(-1f), (double)1f, 74002u);

            var X = arena.doubleMat(s, n);
            var info = Krylov.bcg(in A, in M, in B, ref X, 8 * n, Consts.doubleSqrtEps);
            Assert.IsTrue(info.Solved);

            for (int j = 0; j < s; j++)
            {
                var bj = Row(ref arena, in B, j, n);
                var xj = arena.doubleVec(n);
                Assert.IsTrue(Krylov.cg(in A, in M, in bj, ref xj, 8 * n, Consts.doubleSqrtEps));
                for (int c = 0; c < n; c++)
                    Assert.IsTrue(math.abs((double)X[j, c] - (double)xj[c]) <= Tol() * (1.0 + math.abs((double)xj[c])));
            }

            arena.Dispose();
        }

        // Independent of the scalar solver: pick a KNOWN block solution Xk, form B = A Xk (via the
        // operator's own ApplyBlock), solve, and recover Xk. Verifies the block recurrence end-to-end
        // against a ground-truth solution, not against another solver.
        void KnownSolutionRecovered()
        {
            var arena = new Arena(Allocator.Persistent);

            int n = 20, s = 5;
            var A = BuildDenseSPD(ref arena, n, 75001u);
            var Xk = arena.doubleRandomMat(s, n, (double)(-1f), (double)1f, 75002u);   // known solution

            var B = arena.doubleMat(s, n);
            new doubleDenseOperator(in A).ApplyBlock(in Xk, ref B, s);                 // B[j,:] = A Xk[j,:]

            var X = arena.doubleMat(s, n);
            var info = Krylov.bcg(in A, in B, ref X, 8 * n, Consts.doubleSqrtEps);
            Assert.IsTrue(info.Solved);

            for (int j = 0; j < s; j++)
                for (int c = 0; c < n; c++)
                    Assert.IsTrue(math.abs((double)X[j, c] - (double)Xk[j, c]) <= Tol() * (1.0 + math.abs((double)Xk[j, c])));

            arena.Dispose();
        }

        // Dense n x n -> 1x1-block BSR (mirrors the helper used across the sparse solver tests).
        static doubleBSR DenseToBSR1x1(ref Arena arena, in doubleMxN A, int nnzHint)
        {
            var builder = arena.doubleBSRBuilder(A.M_Rows, A.N_Cols, 1, 1, math.max(nnzHint, 1));
            for (int r = 0; r < A.M_Rows; r++)
                for (int c = 0; c < A.N_Cols; c++)
                    if (A[r, c] != (double)0)
                        builder.AddValue(r, c, A[r, c]);
            return builder.ToBSR(ref arena);
        }
    }

